mapper.sql:
FROM user_profile u WHERE u.deleted_at IS NULL AND u.id<>#{actor}
 AND (LOCATE(#{q},u.nickname)>0 OR CAST(u.id AS CHAR)=#{q})
 AND (u.status=1 OR u.status IN (2,3) AND u.ban_expire_at<=NOW())

mapper.select:
SELECT CAST(u.id AS CHAR) user_id,COALESCE(u.nickname,'') nickname,
NOT EXISTS(SELECT 1 FROM person_account_binding b WHERE b.user_id=u.id AND b.status='ACTIVE' AND b.person_id<>#{person}) available
 ORDER BY u.id LIMIT #{limit} OFFSET #{offset}
